<?php
require_once __DIR__ . '/../config/auth.php';require_admin(['Super Admin','Admissions Officer']);
$q=trim((string)($_GET['q']??''));$sql='SELECT u.id,u.full_name,u.email,u.status,u.created_at,COUNT(a.id) AS applications FROM users u LEFT JOIN applications a ON a.email=u.email WHERE u.role="student"';$params=[];if($q!==''){$sql.=' AND (u.full_name LIKE ? OR u.email LIKE ?)';$term='%'.$q.'%';$params=[$term,$term];}$sql.=' GROUP BY u.id ORDER BY u.created_at DESC LIMIT 200';$stmt=db()->prepare($sql);$stmt->execute($params);$students=$stmt->fetchAll();$pageTitle='Students';include __DIR__.'/../includes/header.php';
?><section class="admin-shell"><aside class="admin-sidebar"><a href="<?= e(url('admin/dashboard.php')) ?>">← Dashboard</a><a href="<?= e(url('admin/applications.php')) ?>">Applications</a></aside><div class="admin-content"><p class="eyebrow">Admissions</p><h1>Students</h1><form class="search-row"><input class="search-field" name="q" placeholder="Search students" value="<?= e($q) ?>"><button class="button">Search</button></form><div class="table-wrap"><table><thead><tr><th>Name</th><th>Email</th><th>Applications</th><th>Status</th><th>Registered</th></tr></thead><tbody><?php foreach($students as $student):?><tr><td><?= e($student['full_name']) ?></td><td><?= e($student['email']) ?></td><td><?= (int)$student['applications'] ?></td><td><?= e($student['status']) ?></td><td><?= e(date('d M Y',strtotime($student['created_at']))) ?></td></tr><?php endforeach;?></tbody></table></div></div></section><?php include __DIR__.'/../includes/footer.php';?>